## ---- 01: Sample Validation Workflow Pseudocode  (qmd line 385) -----------------------

validate_model <- function(model, training_data, holdout_data,
                           benchmarks, thresholds) {
  # 1. Conceptual soundness review
  conceptual <- review_methodology(model$documentation)

  # 2. Data validation
  data_issues <- validate_inputs(training_data, holdout_data)

  # 3. In-sample fit
  in_sample <- compute_metrics(model, training_data)

  # 4. Out-of-sample performance
  oos <- compute_metrics(model, holdout_data)

  # 5. Out-of-time performance
  oot <- rolling_origin_backtest(model, data_timeline)

  # 6. Stability monitoring
  psi <- compute_psi(model, training_data, holdout_data)

  # 7. Benchmark comparison
  bench <- compare_to_benchmarks(model, benchmarks, holdout_data)

  # 8. Stress testing
  stress <- apply_stress_scenarios(model, stress_scenarios)

  # 9. Write validation report
  report <- compile_report(conceptual, data_issues, in_sample, oos,
                           oot, psi, bench, stress)

  # 10. Compare against thresholds and decide
  decision <- decide_pass_fail(report, thresholds)

  # 11. File with MRM
  file_report(report, decision)

  return(list(report = report, decision = decision))
}


## ---- 02: Brier Score and Calibration Plot  (qmd line 454) ----------------------------

library(dplyr)
library(ggplot2)

brier_score <- function(p, y) mean((p - y)^2)

# Calibration plot (reliability diagram)
calibration_plot <- function(p, y, n_bins = 10) {
  bins <- cut(p, breaks = quantile(p, seq(0, 1, length.out = n_bins + 1)),
              include.lowest = TRUE)
  df <- data.frame(p, y, bin = bins) %>%
    group_by(bin) %>%
    summarize(mean_p = mean(p), mean_y = mean(y), n = n())
  ggplot(df, aes(mean_p, mean_y)) +
    geom_line() +
    geom_point() +
    geom_abline(intercept = 0, slope = 1, colour = "red", linetype = 2) +
    coord_cartesian(xlim = c(0, 0.1), ylim = c(0, 0.1)) +
    labs(x = "Predicted", y = "Actual") +
    theme_minimal()
}

# Out-of-time split: fit on 2018-2022, score on 2023+
monthly_panel <- read.csv("data/sample_monthly_panel.csv")
train <- subset(monthly_panel, year <= 2022)
test  <- subset(monthly_panel, year  > 2022)
fit <- glm(prepay_event ~ refi_incentive + age + balance_log +
             factor(sector),
           family = binomial("cloglog"), data = train)
test_preds   <- predict(fit, test, type = "response")
test_actuals <- test$prepay_event

calibration_plot(test_preds, test_actuals)


## ---- 03: AUC and Lift via pROC  (qmd line 491) ---------------------------------------

library(pROC)
library(ggplot2)
roc_obj <- roc(test_actuals, test_preds)
auc(roc_obj)
ggroc(roc_obj) + theme_minimal()

# Lift curve
n_top   <- floor(0.10 * length(test_preds))
top_idx <- order(test_preds, decreasing = TRUE)[seq_len(n_top)]
lift    <- mean(test_actuals[top_idx]) / mean(test_actuals)
lift


## ---- 04: Rolling-Origin Backtest  (qmd line 507) -------------------------------------

backtest <- function(model_fn, data, time_col = "month_id",
                      train_window = 36, horizon = 1) {
  months <- sort(unique(data[[time_col]]))
  results <- list()
  for (i in seq(train_window + 1, length(months) - horizon)) {
    train <- data %>% filter(.data[[time_col]] %in%
                              months[(i - train_window):(i - 1)])
    test  <- data %>% filter(.data[[time_col]] == months[i + horizon - 1])
    fit   <- model_fn(train)
    pred  <- predict(fit, test, type = "response")
    results[[i]] <- data.frame(month = months[i + horizon - 1],
                                pred  = pred,
                                actual = test$prepay_event)
  }
  do.call(rbind, results)
}


## ---- 05: PSI for Drift Monitoring  (qmd line 528) ------------------------------------

psi <- function(actual_vec, expected_vec, n_bins = 10) {
  breaks <- quantile(expected_vec,
                     probs = seq(0, 1, length.out = n_bins + 1),
                     na.rm = TRUE)
  e <- table(cut(expected_vec, breaks, include.lowest = TRUE)) /
       length(expected_vec)
  a <- table(cut(actual_vec, breaks, include.lowest = TRUE)) /
       length(actual_vec)
  sum((a - e) * log((a + 1e-6) / (e + 1e-6)))
}

# Monitor a feature: the current scoring population against the one the
# model was trained on
training_data <- subset(monthly_panel, year <= 2022)
monthly_now   <- subset(monthly_panel, year >= 2024)

psi_now <- psi(monthly_now$refi_incentive,
                training_data$refi_incentive)
flag <- psi_now > 0.25   # alert threshold


