## ---- 07: Time-Dependent AUC  (qmd line 564) ------------------------------------------

library(survAUC)
library(survival)

loan_panel <- read.csv("data/sample_loan_panel.csv")
set.seed(42)
idx   <- sample(nrow(loan_panel), nrow(loan_panel) / 2)
cols  <- c("coupon", "balance_log")
train <- data.frame(age = loan_panel$loan_age, event = loan_panel$event,
                    loan_panel[, cols])[idx, ]
test  <- data.frame(age = loan_panel$loan_age, event = loan_panel$event,
                    loan_panel[, cols])[-idx, ]
fit_cox <- coxph(Surv(age, event) ~ coupon + balance_log, data = train)

times_eval <- seq(12, 120, by = 12)
auc_t <- AUC.uno(Surv(train$age, train$event),
                  Surv(test$age, test$event),
                  predict(fit_cox, test),
                  times = times_eval)
library(ggplot2)
ggplot(data.frame(month = times_eval, auc = auc_t$auc),
       aes(month, auc)) +
  geom_line() +
  geom_point() +
  labs(x = "Months", y = "Time-dependent AUC") +
  theme_minimal()


## ---- 08: Reproducibility: Versioning Run Outputs  (qmd line 594) ---------------------

record_run <- function(model, inputs, outputs) {
  list(
    timestamp     = Sys.time(),
    git_sha       = system("git rev-parse HEAD", intern = TRUE),
    seed          = .GlobalEnv$.Random.seed,
    model_version = packageVersion("oasr"),
    model_hash    = digest::digest(model),
    input_hash    = digest::digest(inputs),
    output_hash   = digest::digest(outputs)
  )
}


## ---- 09: Validation Report Template  (qmd line 610) ----------------------------------

build_validation_report <- function(model, train, test,
                                    predictor_cols, backtest_results) {
  list(
    auc                = auc(roc(test$y, predict(model, test,
                                                 type = "response"))),
    brier              = brier_score(predict(model, test,
                                             type = "response"), test$y),
    calibration_slope  = coef(glm(test$y ~ predict(model, test),
                                  family = binomial))[2],
    psi_features       = sapply(predictor_cols,
                                 function(v) psi(test[[v]], train[[v]])),
    backtest_rmse      = sqrt(mean((backtest_results$pred -
                                      backtest_results$actual)^2))
  )
}


